package sohal.lld.zerodha.order;import sohal.lld.zerodha.entity.Stock;import sohal.lld.zerodha.enums.OrderStatus;import sohal.lld.zerodha.enums.OrderType;import sohal.lld.zerodha.enums.TransactionType;import sohal.lld.zerodha.strategy.LimitOrderStrategy;import sohal.lld.zerodha.strategy.MarketOrderStrategy;import sohal.lld.zerodha.user.User;import java.util.UUID;public class OrderBuilder {    private User user;    private Stock stock;    private TransactionType transactionType;    private OrderType orderType;    private int quantity;    private double price;    public OrderBuilder forUser(User user) {        this.user = user;        return this;    }    public OrderBuilder withStock(Stock stock) {        this.stock = stock;        return this;    }    public OrderBuilder buy(int quantity) {        this.transactionType = TransactionType.BUY;        this.quantity = quantity;        return this;    }    public OrderBuilder sell(int quantity) {        this.transactionType = TransactionType.SELL;        this.quantity = quantity;        return this;    }    public OrderBuilder atMarket() {        this.orderType = OrderType.MARKET;        this.price = 0.0;        return this;    }    public OrderBuilder atLimit(double price) {        this.orderType = OrderType.LIMIT;        this.price = price;        return this;    }    public Order build() {        return new Order(                UUID.randomUUID().toString(),                price,                quantity,                orderType,                user,                stock,                user,                orderType == OrderType.MARKET ? new MarketOrderStrategy() : new LimitOrderStrategy()        );    }}